window.__GAME_TEMPLATES=window.__GAME_TEMPLATES||{};window.__GAME_TEMPLATES["secret"]="<!DOCTYPE html>\n<html lang=\"ru\">\n<head>\n    <meta charset=\"UTF-8\">\n    <meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0, viewport-fit=cover\">\n    <title>Уууу! секрет!</title>\n    <link href=\"https://fonts.googleapis.com/css2?family=Poppins:wght@300;400;500;600;700&display=swap\" rel=\"stylesheet\">\n    \r\n\n    <style>\n/* === Стили из предоставленного chat.txt (увеличенные) === */\n        /*-Body-*/\n        * {\n            box-sizing: border-box;\n        }\n        html, body {\n            height: 100%;\n            margin: 0;\n            padding: 0;\n            font-family: 'Poppins', sans-serif;\n            background: linear-gradient(120deg, #3d3b3b, #0c1113);\n            color: #ffffff;\n            line-height: 1.6;\n            overflow: hidden;\n        }\n        .bg {\n            width: 100%;\n            height: 100%;\n            top: 0;\n            left: 0;\n            z-index: 0;\n            position: absolute;\n            background: url('https://images.unsplash.com/photo-1451186859696-371d9477be93?crop=entropy&fit=crop&fm=jpg&h=975&ixjsv=2.1.0&ixlib=rb-0.3.5&q=80&w=1925') no-repeat 0 0;\n            filter: blur(80px);\n            transform: scale(1.2);\n        }\n        /*-Chat-*/\n        .chat {\n            /* Увеличиваем размеры */\n            width: 90%; /* Ширина 90% от контейнера */\n            max-width: 600px; /* Максимальная ширина 600px */\n            height: 85vh; /* Высота 85% от viewport height */\n            max-height: 700px; /* Максимальная высота 700px */\n            /* Остальные стили из chat.txt */\n            z-index: 2;\n            overflow: hidden;\n            box-shadow: 0 5px 30px rgba(20, 20, 20, 0.2);\n            background: rgba(20, 20, 20, 0.5);\n            border-radius: 20px;\n            display: flex;\n            justify-content: space-between;\n            flex-direction: column;\n            position: relative;\n            margin: 2vh auto; /* Центрируем по горизонтали и добавляем отступы */\n        }\n        /*-Chat Title-*/\n        .chat-title {\n            flex: 0 1 45px;\n            position: relative;\n            z-index: 2;\n            background: rgba(12, 11, 11, 0.2);\n            color: #ffffff;\n            text-transform: uppercase;\n            text-align: left;\n            padding: 10px 10px 10px 50px;\n        }\n        .chat-title h1, .chat-title h2 {\n            font-weight: normal;\n            font-size: 14px; /* Увеличиваем шрифт заголовка */\n            margin: 0;\n            padding: 0;\n        }\n        .chat-title h2 {\n            color: rgb(0, 116, 39);\n            font-size: 10px; /* Увеличиваем шрифт подзаголовка */\n            letter-spacing: 1px;\n        }\n        .chat-title .avatar {\n            position: absolute;\n            z-index: 1;\n            top: 8px;\n            left: 9px;\n            border-radius: 30px;\n            width: 30px;\n            height: 30px;\n            overflow: hidden;\n            margin: 0;\n            padding: 0;\n            border: 2px solid rgba(235, 235, 235, 0.329);\n        }\n        .chat-title .avatar img {\n            width: 100%;\n            height: auto;\n        }\n        /*-Messages-*/\n        .messages {\n            flex: 1 1 auto;\n            color: rgba(255, 255, 255, 0.877);\n            overflow-y: auto;\n            position: relative;\n            width: 100%;\n            padding: 10px 5px;\n            display: flex;\n            flex-direction: column-reverse; /* Новые сообщения сверху */\n            /* --- Стилизация скроллбара --- */\n            scrollbar-width: thin;\n            scrollbar-color: rgba(114, 114, 114, 0.5) transparent;\n        }\n        .messages::-webkit-scrollbar {\n            width: 8px;\n        }\n        .messages::-webkit-scrollbar-track {\n            background: transparent;\n        }\n        .messages::-webkit-scrollbar-thumb {\n            background-color: rgba(114, 114, 114, 0.5);\n            border-radius: 4px;\n        }\n        .messages::-webkit-scrollbar-thumb:hover {\n            background-color: rgba(114, 114, 114, 0.7);\n        }\n        /* --- Конец стилей скроллбара --- */\n        .message {\n            clear: both;\n            float: left;\n            padding: 8px 12px 9px; /* Увеличиваем padding */\n            border-radius: 12px 12px 12px 0; /* Увеличиваем радиус */\n            background: rgba(0, 0, 0, .3);\n            margin: 10px 0; /* Увеличиваем margin */\n            font-size: 14px; /* Увеличиваем размер шрифта */\n            line-height: 1.5; /* Увеличиваем межстрочный интервал */\n            margin-left: 35px; /* Отступ для аватарки */\n            position: relative;\n            text-shadow: 0 1px 1px rgba(0, 0, 0, .2);\n            animation: fadeInUp 0.3s ease;\n            max-width: 80%;\n            word-wrap: break-word;\n            /* --- Добавляем display: inline-block для адаптации фона --- */\n            display: inline-block;\n            /* --- Конец добавления --- */\n        }\n        @keyframes fadeInUp {\n            from {\n                opacity: 0;\n                transform: translateY(10px);\n            }\n            to {\n                opacity: 1;\n                transform: translateY(0);\n            }\n        }\n        .message .text {\n            margin-bottom: 5px;\n        }\n        .message .timestamp {\n            position: absolute;\n            bottom: -15px;\n            font-size: 11px; /* Увеличиваем размер шрифта времени */\n            color: rgba(255, 255, 255, .3);\n            text-align: right;\n            right: 0;\n        }\n        .message .avatar {\n            position: absolute;\n            z-index: 1;\n            bottom: -15px;\n            left: -35px;\n            border-radius: 30px;\n            width: 30px;\n            height: 30px;\n            overflow: hidden;\n            margin: 0;\n            padding: 0;\n            border: 2px solid rgba(255, 255, 255, 0.24);\n        }\n        .message .avatar img {\n            width: 100%;\n            height: auto;\n        }\n        /* --- Стили для сообщения пользователя (message-new) --- */\n        .message.message-new {\n            float: right;\n            color: #fff;\n            text-align: right;\n            background: linear-gradient(120deg, #00000088, #5c5b5b1a); /* Фон из chat.txt */\n            border-radius: 12px 12px 0 12px; /* Увеличиваем радиус */\n            margin-right: 35px; /* Отступ для аватарки справа */\n            margin-left: 0;\n            /* --- display: inline-block уже задан выше, наследуется --- */\n        }\n        .message.message-new .timestamp {\n            right: auto;\n            text-align: left;\n        }\n        .message.message-new .avatar {\n            left: auto;\n            right: -35px;\n        }\n        /* --- Конец стилей сообщения пользователя --- */\n        /* === Конец стилей чата === */\n        /* === Стили для комнаты === */\n        .lisa-container {\n            max-width: 900px; /* Увеличиваем максимальную ширину контейнера */\n            height: 95vh; /* Увеличиваем высоту контейнера */\n            margin: 2vh auto;\n            padding: 1rem;\n            display: flex;\n            flex-direction: column;\n        }\n        .back-btn {\n            align-self: flex-start;\n            padding: 0.8rem 1.5rem;\n            background: linear-gradient(120deg, #111312d5, #45464671);\n            backdrop-filter: blur(10px);\n            border: 1px solid rgb(65, 63, 63);\n            border-radius: 25px;\n            color: rgb(255, 255, 255);\n            text-decoration: none;\n            font-weight: 500;\n            font-size: 0.9rem;\n            transition: all 0.3s ease;\n            margin-bottom: 1rem;\n            z-index: 2; /* Выше фона */\n        }\n        .back-btn:hover {\n            background: rgba(255, 255, 255, 0.2);\n            transform: translateY(-1px);\n        }\n        /* === Стили для вариантов ответов === */\n        .replies-container {\n            padding: 10px;\n            border-top: 1px solid rgba(255, 255, 255, 0.1);\n            display: flex;\n            flex-wrap: wrap;\n            gap: 10px;\n        }\n        .reply-btn {\n            flex: 1;\n            min-width: 120px; /* Минимальная ширина кнопки */\n            padding: 10px 15px;\n            border-radius: 20px;\n            border: none;\n            background: linear-gradient(120deg, #3f3e3e80, #20202081);\n            color: white;\n            cursor: pointer;\n            transition: background 0.3s ease;\n            font-size: 0.9rem;\n            text-align: center;\n        }\n        .reply-btn:hover {\n            background: rgba(114, 114, 114, 0.9);\n        }\n        .reply-btn:disabled {\n            background: rgba(106, 90, 205, 0.3);\n            cursor: not-allowed;\n        }\n        /* === Стили для модального окна с фото === */\n        .modal-overlay {\n            position: fixed;\n            top: 0;\n            left: 0;\n            width: 100%;\n            height: 100%;\n            background: rgba(0, 0, 0, 0.7); /* Полупрозрачный чёрный фон */\n            backdrop-filter: blur(5px); /* Размытие фона */\n            display: flex;\n            justify-content: center;\n            align-items: center;\n            z-index: 10000; /* Очень высокий z-index */\n            opacity: 0;\n            visibility: hidden;\n            transition: opacity 0.3s ease, visibility 0.3s ease;\n        }\n        .modal-overlay.show {\n            opacity: 1;\n            visibility: visible;\n        }\n        .modal-content {\n            background: rgba(26, 26, 26, 0.9); /* Тёмный полупрозрачный фон */\n            backdrop-filter: blur(10px); /* Более сильное размытие внутри окна */\n            border-radius: 16px;\n            padding: 2rem;\n            text-align: center;\n            box-shadow: 0 8px 32px rgba(0, 0, 0, 0.5); /* Тень */\n            border: 1px solid rgba(255, 255, 255, 0.1); /* Тонкая обводка */\n            max-width: 90%;\n            width: auto;\n            position: relative; /* Для позиционирования крестика */\n        }\n        .modal-content img {\n            max-width: 100%;\n            max-height: 70vh; /* Ограничиваем высоту */\n            border-radius: 10px;\n        }\n        .close-modal {\n            position: absolute;\n            top: 10px;\n            right: 10px;\n            background: rgba(255, 255, 255, 0.1);\n            border: none;\n            color: white;\n            font-size: 1.5rem;\n            cursor: pointer;\n            width: 30px;\n            height: 30px;\n            border-radius: 50%;\n            display: flex;\n            justify-content: center;\n            align-items: center;\n        }\n        .close-modal:hover {\n            background: rgba(255, 255, 255, 0.2);\n        }\n        /* === Конец стилей модального окна === */\n    </style>\n    <link rel=\"stylesheet\" href=\"../css/room-effects.css\">\n    <style id=\"mobile-fix\">\n@media (max-width: 768px) {\n    html, body { height: 100%; overflow: hidden; }\n    .bg { filter: blur(50px); }\n    .lisa-container {\n        max-width: none;\n        height: 100svh;\n        margin: 0;\n        padding: calc(6px + env(safe-area-inset-top)) 8px calc(6px + env(safe-area-inset-bottom));\n    }\n    .back-btn { padding: .5rem 1rem; font-size: .8rem; margin-bottom: .5rem; }\n    .chat {\n        width: 100%;\n        height: auto;\n        max-height: none;\n        flex: 1 1 auto;\n        min-height: 0;\n        margin: 0;\n        border-radius: 16px;\n    }\n    .chat-title { padding-left: 46px; }\n    .message { max-width: 86%; margin-left: 30px; }\n    .message .avatar { left: -30px; width: 26px; height: 26px; }\n    .message.message-new { margin-right: 30px; }\n    .message.message-new .avatar { right: -30px; }\n    .replies-container { gap: 8px; }\n    .reply-btn { min-width: 0; flex: 1 1 45%; padding: 10px 8px; font-size: .82rem; }\n}\n    </style>\n    <script src=\"../js/room-effects.js\" defer></script>\n<style id=\"tg-theme\">\n/* ================= Telegram-стиль для секретного чата ================= */\n@property --h1 {\n    syntax: \"<number>\";\n    inherits: true;\n    initial-value: 214;\n}\n@property --h2 {\n    syntax: \"<number>\";\n    inherits: true;\n    initial-value: 270;\n}\n\nhtml, body {\n    height: 100%;\n    margin: 0;\n    overflow: hidden;\n    background: #05070a;\n}\n\nbody {\n    --h1: 214;\n    --h2: 270;\n    transition: --h1 1.4s ease, --h2 1.4s ease;\n    font-family: 'Poppins', sans-serif;\n    color: #e9eff7;\n    -webkit-font-smoothing: antialiased;\n}\n\n/* --- Фон: тёмные переливающиеся градиенты --- */\n.bg {\n    position: fixed;\n    inset: 0;\n    z-index: 0;\n    background:\n        radial-gradient(70vmax 70vmax at 12% 4%, hsl(calc(var(--h1) * 1deg) 55% 24% / 0.55), transparent 62%),\n        radial-gradient(65vmax 65vmax at 92% 96%, hsl(calc(var(--h2) * 1deg) 60% 22% / 0.5), transparent 62%),\n        linear-gradient(165deg, #06080c 0%, #0b1017 45%, #05070a 100%);\n    filter: none;\n    transform: none;\n    transition: none;\n}\n.bg::after {\n    content: \"\";\n    position: absolute;\n    inset: -18%;\n    background: radial-gradient(circle at 35% 45%, hsl(calc(var(--h2) * 1deg) 70% 58% / 0.14), transparent 55%);\n    animation: tgDrift 26s ease-in-out infinite alternate;\n}\n@keyframes tgDrift {\n    from { transform: translate3d(-4%, -3%, 0) scale(1); }\n    to { transform: translate3d(5%, 4%, 0) scale(1.15); }\n}\n\n/* --- Каркас --- */\n.lisa-container {\n    position: relative;\n    z-index: 1;\n    max-width: 760px;\n    width: 100%;\n    height: 100dvh;\n    margin: 0 auto;\n    padding: max(10px, env(safe-area-inset-top)) 12px max(10px, env(safe-area-inset-bottom));\n    display: flex;\n    flex-direction: column;\n    gap: 8px;\n}\n\n.back-btn {\n    align-self: flex-start;\n    margin: 0;\n    padding: 7px 14px;\n    font-size: 13px;\n    font-weight: 500;\n    color: #d7e2ee;\n    background: rgba(22, 27, 36, 0.72);\n    border: 1px solid rgba(255, 255, 255, 0.08);\n    border-radius: 999px;\n    backdrop-filter: blur(10px);\n    -webkit-backdrop-filter: blur(10px);\n    transition: background 0.2s ease, transform 0.2s ease;\n    z-index: 3;\n}\n.back-btn:hover {\n    background: rgba(38, 46, 60, 0.9);\n    transform: translateY(-1px);\n}\n.back-btn:active {\n    transform: scale(0.97);\n}\n\n/* --- Окно чата --- */\n.chat {\n    flex: 1 1 auto;\n    min-height: 0;\n    width: 100%;\n    max-width: none;\n    height: auto;\n    max-height: none;\n    margin: 0;\n    display: flex;\n    flex-direction: column;\n    overflow: hidden;\n    border-radius: 18px;\n    background: rgba(14, 18, 25, 0.66);\n    border: 1px solid rgba(255, 255, 255, 0.07);\n    box-shadow: 0 18px 50px rgba(0, 0, 0, 0.45);\n    backdrop-filter: blur(16px);\n    -webkit-backdrop-filter: blur(16px);\n}\n\n/* --- Шапка --- */\n.chat-title {\n    flex: 0 0 auto;\n    display: flex;\n    align-items: center;\n    gap: 12px;\n    padding: 10px 14px 10px 62px;\n    background: rgba(20, 25, 34, 0.85);\n    border-bottom: 1px solid rgba(255, 255, 255, 0.07);\n    text-transform: none;\n}\n.chat-title .avatar {\n    top: 50%;\n    left: 12px;\n    width: 40px;\n    height: 40px;\n    transform: translateY(-50%);\n    border-radius: 50%;\n    border: 1px solid rgba(255, 255, 255, 0.16);\n    cursor: pointer;\n    transition: transform 0.2s ease, box-shadow 0.2s ease;\n}\n.chat-title .avatar:hover {\n    transform: translateY(-50%) scale(1.06);\n    box-shadow: 0 0 0 3px rgba(255, 255, 255, 0.08);\n}\n.chat-title .avatar img {\n    width: 100%;\n    height: 100%;\n    object-fit: cover;\n}\n.chat-title .user-info {\n    min-width: 0;\n}\n.chat-title h1 {\n    font-size: 15px;\n    font-weight: 600;\n    margin: 0;\n    color: #f3f7fb;\n    white-space: nowrap;\n    overflow: hidden;\n    text-overflow: ellipsis;\n}\n.chat-title h2 {\n    margin: 1px 0 0;\n    font-size: 11.5px;\n    letter-spacing: 0.02em;\n    color: #4ade80;\n    transition: color 0.2s ease;\n}\n.chat-title h2.is-typing {\n    color: #9fb0c4;\n}\n\n/* --- Лента сообщений --- */\n.messages {\n    flex: 1 1 auto;\n    min-height: 0;\n    display: flex;\n    flex-direction: column;\n    align-items: flex-start;\n    gap: 3px;\n    padding: 14px 14px 8px;\n    overflow-y: auto;\n    overflow-x: hidden;\n    scroll-behavior: smooth;\n    scrollbar-width: thin;\n    scrollbar-color: rgba(255, 255, 255, 0.16) transparent;\n    color: #e9eff7;\n}\n.messages::-webkit-scrollbar { width: 6px; }\n.messages::-webkit-scrollbar-track { background: transparent; }\n.messages::-webkit-scrollbar-thumb {\n    background: rgba(255, 255, 255, 0.16);\n    border-radius: 6px;\n}\n\n.message {\n    float: none;\n    clear: both;\n    display: block;\n    position: relative;\n    max-width: min(78%, 520px);\n    margin: 0 0 0 34px;\n    padding: 8px 12px 20px;\n    border-radius: 16px 16px 16px 4px;\n    background: rgba(30, 37, 48, 0.92);\n    border: 1px solid rgba(255, 255, 255, 0.045);\n    box-shadow: 0 3px 14px rgba(0, 0, 0, 0.22);\n    font-size: 14.5px;\n    line-height: 1.5;\n    text-align: left;\n    text-shadow: none;\n    color: #e9eff7;\n    animation: tgMsgIn 0.24s ease both;\n    word-wrap: break-word;\n    overflow-wrap: anywhere;\n}\n@keyframes tgMsgIn {\n    from { opacity: 0; transform: translateY(8px) scale(0.985); }\n    to { opacity: 1; transform: translateY(0) scale(1); }\n}\n\n.message.message-new {\n    align-self: flex-end;\n    margin: 0 34px 0 0;\n    border-radius: 16px 16px 4px 16px;\n    background: linear-gradient(135deg,\n        hsl(calc(var(--h2) * 1deg) 42% 30%),\n        hsl(calc(var(--h1) * 1deg) 48% 22%));\n    border-color: rgba(255, 255, 255, 0.08);\n    color: #ffffff;\n    text-align: left;\n}\n\n.message .text {\n    margin: 0;\n    white-space: pre-wrap;\n}\n\n.message .timestamp {\n    position: absolute;\n    right: 10px;\n    bottom: 5px;\n    left: auto;\n    font-size: 10px;\n    color: rgba(255, 255, 255, 0.5);\n    text-align: right;\n}\n.message.message-new .timestamp {\n    right: 10px;\n    text-align: right;\n    color: rgba(255, 255, 255, 0.62);\n}\n\n.message .avatar {\n    position: absolute;\n    left: -34px;\n    bottom: 0;\n    width: 28px;\n    height: 28px;\n    border-radius: 50%;\n    overflow: hidden;\n    border: 1px solid rgba(255, 255, 255, 0.14);\n    background: #1a2029;\n}\n.message .avatar img {\n    width: 100%;\n    height: 100%;\n    object-fit: cover;\n    display: block;\n}\n.message.message-new .avatar {\n    left: auto;\n    right: -34px;\n}\n\n/* --- Индикатор набора --- */\n.tg-typing {\n    display: none;\n    align-self: flex-start;\n    margin: 2px 0 0 34px;\n    padding: 11px 14px;\n    border-radius: 16px 16px 16px 4px;\n    background: rgba(30, 37, 48, 0.92);\n    border: 1px solid rgba(255, 255, 255, 0.045);\n    gap: 5px;\n}\n.tg-typing.is-visible {\n    display: inline-flex;\n}\n.tg-typing span {\n    width: 6px;\n    height: 6px;\n    border-radius: 50%;\n    background: #9fb0c4;\n    animation: tgDot 1.2s infinite ease-in-out;\n}\n.tg-typing span:nth-child(2) { animation-delay: 0.15s; }\n.tg-typing span:nth-child(3) { animation-delay: 0.3s; }\n@keyframes tgDot {\n    0%, 60%, 100% { opacity: 0.35; transform: translateY(0); }\n    30% { opacity: 1; transform: translateY(-3px); }\n}\n\n/* --- Панель ответов --- */\n.replies-container {\n    flex: 0 0 auto;\n    display: flex;\n    flex-wrap: wrap;\n    justify-content: flex-end;\n    gap: 8px;\n    padding: 10px 12px;\n    border-top: 1px solid rgba(255, 255, 255, 0.08);\n    background: rgba(18, 23, 31, 0.9);\n}\n.reply-btn {\n    flex: 0 1 auto;\n    min-width: 0;\n    max-width: 100%;\n    padding: 9px 14px;\n    border-radius: 18px;\n    border: 1px solid rgba(255, 255, 255, 0.1);\n    background: rgba(35, 43, 56, 0.95);\n    color: #dde7f2;\n    font: inherit;\n    font-size: 13px;\n    line-height: 1.35;\n    text-align: left;\n    cursor: pointer;\n    transition: background 0.2s ease, border-color 0.2s ease, transform 0.15s ease;\n}\n.reply-btn:hover {\n    background: rgba(52, 64, 82, 0.98);\n    border-color: rgba(255, 255, 255, 0.18);\n    transform: translateY(-1px);\n}\n.reply-btn:active {\n    transform: scale(0.97);\n}\n.reply-btn:disabled {\n    opacity: 0.5;\n    cursor: default;\n    transform: none;\n}\n\n/* --- Модальное фото --- */\n.modal-content {\n    background: rgba(18, 22, 30, 0.94);\n    border: 1px solid rgba(255, 255, 255, 0.1);\n}\n\n/* --- Телефоны --- */\n@media (max-width: 768px) {\n    .lisa-container {\n        max-width: none;\n        height: 100dvh;\n        padding: max(6px, env(safe-area-inset-top)) 8px max(6px, env(safe-area-inset-bottom));\n        gap: 6px;\n    }\n    .back-btn {\n        padding: 5px 11px;\n        font-size: 12px;\n    }\n    .chat {\n        border-radius: 14px;\n    }\n    .chat-title {\n        padding: 8px 12px 8px 56px;\n    }\n    .chat-title .avatar {\n        width: 36px;\n        height: 36px;\n        left: 10px;\n    }\n    .messages {\n        padding: 10px 10px 6px;\n    }\n    .message {\n        max-width: 84%;\n        font-size: 14px;\n        margin-left: 30px;\n    }\n    .message.message-new {\n        margin-right: 30px;\n    }\n    .message .avatar {\n        left: -30px;\n        width: 24px;\n        height: 24px;\n    }\n    .message.message-new .avatar {\n        right: -30px;\n    }\n    .reply-btn {\n        font-size: 12.5px;\n        padding: 8px 12px;\n    }\n    .replies-container {\n        gap: 6px;\n        padding: 8px 10px;\n        justify-content: stretch;\n    }\n    .reply-btn {\n        flex: 1 1 100%;\n    }\n}\n\n@media (prefers-reduced-motion: reduce) {\n    .bg::after { animation: none; }\n    .message { animation: none; }\n    .tg-typing span { animation: none; }\n}\n\n    </style>\n</head>\n<body>\n    <div class=\"bg\"></div> <!-- Фон -->\n    <div class=\"lisa-container\">\n        <a href=\"../index.html\" class=\"back-btn\">← Обратно!</a>\n        <div class=\"chat\">\n            <div class=\"chat-title\">\n                <div class=\"avatar\">\n                    <img src=\"../assets/images/secret/9.png\" alt=\"Аватар пользователя\">\n                </div>\n                <div class=\"user-info\">\n                    <h1>Плюшевый мишка</h1>\n                    <h2>в сети</h2>\n                </div>\n            </div>\n            <div class=\"messages\" id=\"messages\">\n                <!-- Сообщения будут добавляться сюда -->\n            </div>\n            <!-- Контейнер для кнопок ответов -->\n            <div class=\"replies-container\" id=\"repliesContainer\" style=\"display: none;\">\n                <!-- Кнопки будут добавляться сюда -->\n            </div>\n        </div>\n    </div>\n    <!-- Модальное окно для фото -->\n    <div class=\"modal-overlay\" id=\"photoModal\">\n        <div class=\"modal-content\">\n            <button class=\"close-modal\" id=\"closeModalBtn\">&times;</button>\n            <img id=\"modalImage\" src=\"\" alt=\"Увеличенное фото\">\n        </div>\n    </div>\n    <script>\n        document.addEventListener('DOMContentLoaded', function () {\n            var messagesDiv = document.getElementById('messages');\n            var repliesContainer = document.getElementById('repliesContainer');\n            var userAvatar = document.querySelector('.chat-title .avatar');\n            var statusEl = document.querySelector('.chat-title h2');\n            var photoModal = document.getElementById('photoModal');\n            var modalImage = document.getElementById('modalImage');\n            var closeModalBtn = document.getElementById('closeModalBtn');\n\n            var BOT_AVATAR = '../assets/images/secret/10.png';\n            var USER_AVATAR = '../assets/images/secret/8.png';\n            var waiting = false;\n            var started = false;\n\n            const botResponses = {\n                start: {\n                    text: \"А ты как сюда попала, ты что, шпион?\",\n                    replies: [\n                        { text: \"Да димка\", next: 'ok' },\n                        { text: \"Нет..?\", next: 'bad' },\n                        { text: \"Возможно\", next: 'question' }\n                    ]\n                },\n                ok: {\n                    text: \"Ну и чего ты здесь забыла? это мой уголок так то. Тебя сюда не впускали любимая!\",\n                    replies: [\n                        { text: \"Ну и че\", next: 'busy' },\n                        { text: \"Да пох\", next: 'relax' },\n                        { text: \"Ну извини..\", next: 'question' }\n                    ]\n                },\n                bad: {\n                    text: \"Тогда возможно тебя ждет разговор дома...\",\n                    replies: [\n                        { text: \"О, да?\", next: 'yes' },\n                        { text: \"Ну я жду\", next: 'no' },\n                        { text: \"Это тебя ждет разговор дома!\", next: 'question' }\n                    ]\n                },\n                question: {\n                    text: \"Это тебя ждет разговор дома! За такое по жопке дают, знаешь? Что в оправдание скажешь?\",\n                    replies: [\n                        { text: \"Люблю...\", next: 'clarify' },\n                        { text: \"Ну............\", next: 'change_topic' }\n                    ]\n                },\n                busy: {\n                    text: \"Ну и че? Я вообще то для тебя сюрприз готовил так то, а ты вот так взяла и все нашла и все испортила, ну и как тебе сюрпризы такие готовить блин :(\",\n                    replies: [\n                        { text: \"Ну приготовишь еще сюрпризы мне, не бесись\", next: 'agree' },\n                        { text: \"Все все, ладно, извини\", next: 'disagree' }\n                    ]\n                },\n                relax: {\n                    text: \"О как, пох?? Вот так и делай для тебя что нибудь приятное, а я ведь старался, силушки вкладывал!\",\n                    replies: [\n                        { text: \"Ты все равно умничка\", next: 'umniche' },\n                        { text: \"Ну чего ты, спасибо и за это Дим\", next: 'thank_you' },\n                        { text: \"Не переживай ты так, Дим\", next: 'worry' }\n                    ]\n                },\n                yes: {\n                    text: \"Ну да, а ты что думала все так просто обойдется? Нет нет нет родная, жизнь не так сладка как кажется\",\n                    replies: [\n                        { text: \"Но я ведь тебя люблю сильно!\", next: 'clarify' },\n                        { text: \"Ну тут мои полномочия все..\", next: 'change_topic' }\n                    ]\n                },\n                no: {\n                    text: \"Ну и жди, вот потом посмотрим как ты милашка запоешь\",\n                    replies: [\n                        { text: \"Это все равно мило Димка\", next: 'milo' },\n                        { text: \"Прости Димка, я вообще сюда случайно тыкнула, но это очень мило\", next: 'sluchayno' }\n                    ]\n                },\n                agree: {\n                    text: \"Приготовлю, но просто это хотелось сделать прям вау, а порой так сложно так делать, что и в голову не лезут все эти слова и словушки, но я всеравно рад что тебе это показал хоть в таком виде\",\n                    replies: [\n                        { text: \"Это правда мило что ты сделал, да и вообще сайт прикольный, мне все нравиться, ты молодец\", next: 'milo2' },\n                        { text: \"Извини что я все порчу...\", next: 'disagree' }\n                    ]\n                },\n                disagree: {\n                    text: \"Да ладно, ничего страшного, зато это показывает какая ты любопытная, что мило на самом деле, чудо ты такое\",\n                    replies: [\n                        { text: \"Спасибо Дим, ты тоже милый\", next: 'mily' },\n                        { text: \"Ну я не знаю что сказать..\", next: 'change_topic' }\n                    ]\n                },\n                change_topic: {\n                    text: \"Ладно, проехали. можешь просто для приличия сказать одно слово, а то как то не то\",\n                    replies: [\n                        { text: \"Люблю\", next: 'love' },\n                        { text: \"Обнимаю\", next: 'hug' },\n                        { text: \"Мишка ты\", next: 'bear' }\n                    ]\n                },\n                clarify: {\n                    text: \"И я тебя сильно люблю лиз, ты милая даже в таких ситуациях на самом деле, да и вообще милая, как тебя так злиться?\",\n                    replies: [\n                        { text: \"Спасибо Дим, ты лучший\", next: 'end' },\n                        { text: \"Не расстраивайся Дим, все классно получилось и я рада тому что ты сделал\", next: 'end' }\n                    ]\n                },\n                umniche: {\n                    text: \"Умничка... Да, но все равно обидно так то, вообще блин..\",\n                    replies: [\n                        { text: \"Ну извини, ты сам мне дал свободу действий\", next: 'disagree' },\n                        { text: \"Да ничего страшного ведь не случилось, все хорошо\", next: 'ladno' }\n                    ]\n                },\n                thank_you: {\n                    text: \"Ну не зна что, но ты как то в следующий раз аккуратно тыкай, а то вдруг.....\",\n                    replies: [\n                        { text: \"Прям вдруг.....? Все хорошо ведь Димка\", next: 'preuvel' },\n                        { text: \"Ты все равно молодчинка Дима\", next: 'molodec' }\n                    ]\n                },\n                worry: {\n                    text: \"Ну... ладно, все равно сделал это специально\",\n                    replies: [\n                        { text: \"Ну вот и все, не бесись\", next: 'clarify' },\n                        { text: \"Ну вот и все, ладно, да??\", next: 'ladno' }\n                    ]\n                },\n                milo: {\n                    text: \"Да, мило получилось, доволен тем что получилось, хоть и есть много где проблем, но я же не супер программист ведь, так что радуемся тому что есть\",\n                    replies: [\n                        { text: \"Да все круто, что еще сказать?\", next: 'esho' },\n                        { text: \"Ну вот и все мишка🧸\", next: 'bear' }\n                    ]\n                },\n                sluchayno: {\n                    text: \"Случайности не случайны так то\",\n                    replies: [\n                        { text: \"Короче мило это, все\", next: 'tsenya' },\n                        { text: \"Можешь просто сказать что любишь, че бесится то\", next: 'love' }\n                    ]\n                },\n                milo2: {\n                    text: \"Мило и прикольно, а еще, круто так то!\",\n                    replies: [\n                        { text: \"Ну вдруг чего прости\", next: 'disagree' },\n                        { text: \"Да, красиво получился, ничего не скажешь\", next: 'krasivo' }\n                    ]\n                },\n                mily: {\n                    text: \"Ты тоже мили, даже когда пытаешься ломать систему)\",\n                    replies: [\n                        { text: \"Ну такая я, да)\", next: 'prosti' },\n                        { text: \"ну ты мишка короч 🧸\", next: 'bear' }\n                    ]\n                },\n                love: {\n                    text: \"Любишь прям? а я еще сильнее тебя люблю\",\n                    replies: [\n                        { text: \"Нет, я сильнее тебя люблю!\", next: 'mnogo' },\n                        { text: \"Еще бы сказал обратное)\", next: 'esho' }\n                    ]\n                },\n                hug: {\n                    text: \"Обнимашки от обояшки?\",\n                    replies: [\n                        { text: \"Когда увидемся их будет много\", next: 'uvim' },\n                        { text: \"Ты бы еще обнял меня!\", next: 'virtual' }\n                    ]\n                },\n                bear: {\n                    text: \"Мишка, вообще ты мишка у меня, что я так то\",\n                    replies: [\n                        { text: \"Мишка и мишка, что сразу на меня стрелки переводить. ты что не мишка?\", next: 'bear2' },\n                        { text: \"Ну и ты плюшевый мишка, что нет??\", next: 'bear2' }\n                    ]\n                },\n                bear2: {\n                    text: \"Я тоже мишка и вот мы две мишки, а что дальше то?\",\n                    replies: [\n                        { text: \"Ну вот и все, вдвоем, все, решили? Люблю просто и все, не бузи\", next: 'clarify' },\n                        { text: \"Ну и все, люблю\", next: 'clarify' }\n                    ]\n                },\n                ladno: {\n                    text: \"Ладно, что еще тут добавить, просто чудо с двумя ножками и ручками, обижатся глупо, бесится я не смогу на тебя долго, так что живем дальше, да?\",\n                    replies: [\n                        { text: \"Ну ты если что предупреждай куда не тыкать хоть\", next: 'postaraysya' },\n                        { text: \"Да, живем дальше. Люблю\", next: 'clarify' }\n                    ]\n                },\n                preuvel: {\n                    text: \"Ну это не прям большая катастрофа, но все таки\",\n                    replies: [\n                        { text: \"Да мне все равно нравится это, не бесись\", next: 'tsenya' },\n                        { text: \"Ну прости, чего ты\", next: 'disagree' }\n                    ]\n                },\n                molodec: {\n                    text: \"Спасибо Лиз, ладно, переживу как нибудь свой пробел\",\n                    replies: [\n                        { text: \"Все, не злимся?\", next: 'zly' },\n                        { text: \"Ну ты хоть и не доработал, то все равно лучший, люблю тебя так то\", next: 'clarify' }\n                    ]\n                },\n                esho: {\n                    text: \"Не, ну... честно я уже не знаю что еще отвечать, ты бы видела эти огромные строки диалогов которые я каждый прошу написать. прости, но просто это ужас в моменте пытаться все держать в уме и вести такую ролку или что то такого, в общем ладно, пишем дальше, извини, тут типо должно быть 'сообщение от разработчика', так что считаем это пасхалкой, пон?\",\n                    replies: [\n                        { text: \"Ну допустим, не знаю..\", next: 'ne_znay' },\n                        { text: \"Ну наверное?\", next: 'prav' }\n                    ]\n                },\n                tsenya: {\n                    text: \"Ценим ценим, я ценю так то, а ты?\",\n                    replies: [\n                        { text: \"Ценю, а че, нет? показать что ли как ценю??\", next: 'pokazat' },\n                        { text: \"Я ценю\", next: 'tsenya2' }\n                    ]\n                },\n                krasivo: {\n                    text: \"Мило и красиво. Ты милая и красивая так то лиз\",\n                    replies: [\n                        { text: \"А вот нет. Почему ты так считаешь?\", next: 'pochemu' },\n                        { text: \"Спасибо Димка\", next: 'prav' }\n                    ]\n                },\n                prosti: {\n                    text: \"Ладненько, все нормик, не переживаем так сильно, да?\",\n                    replies: [\n                        { text: \"Ну прости вдруг чего \", next: 'izvin' },  \n                        { text: \"Не переживаем, но извиняюсь\", next: 'izvin' }\n                    ]\n                },\n                mnogo: {\n                    text: \"Много как...... как... не знаю даже. Много чего? любви?\",\n                    replies: [\n                        { text: \"Я не могу сейчас говорить плохое\", next: 'ne_mogu' },\n                        { text: \"Да, димка!\", next: 'prav' }\n                    ]\n                },\n                uvim: {\n                    text: \"Ну посмотрим, а так, мне с тобой и сейчас хорошо\",\n                    replies: [\n                        { text: \"Мне тоже с тобой хорошо Дим\", next: 'ne_port' },\n                        { text: \"Ты мили\", next: 'ne_port' }\n                    ]\n                },\n                virtual: {\n                    text: \"Как же хочу тебя заобнимать сейчас..\",\n                    replies: [\n                        { text: \"Я мысленно уже тебя обнимаю, а как увидимся то наобнимаемся сколько влезет\", next: 'uvim' },\n                        { text: \"Можешь обнять меня в мыслях\", next: 'mysli' }\n                    ]\n                },\n                postaraysya: {\n                    text: \"Постараюсь, а может и не постараюсь, а может не знаю..\",\n                    replies: [\n                        { text: \"Постарайся (Хз в чем, я запутался о чем там..)\", next: 'obeshay' },\n                        { text: \"Ну ты постарайся блин, а так оки\", next: 'horosho' }\n                    ]\n                },\n                zly: {\n                    text: \"Ладненько, ты умничка Лиз, просто так вот\",\n                    replies: [\n                        { text: \"Не обижайся только ладно?\", next: 'ladno' },\n                        { text: \"ты тоже обояшка\", next: 'prav' }\n                    ]\n                },\n                ne_znay: {\n                    text: \"Ну допустим я тоже не знаю..\",\n                    replies: [\n                        { text: \"А ты подумай\", next: 'podumay' },\n                        { text: \"Ну и что дальше?\", next: 'podumay' }\n                    ]\n                },\n                prav: {\n                    text: \"Да лизаветка! В общем ладно, не злюсь\",\n                    replies: [\n                        { text: \"ну вот и все хорошо тогда\", next: 'zato' },\n                        { text: \"Люблю тебя так то\", next: 'clarify' }\n                    ]\n                },\n                tsenya2: {\n                    text: \"Ценим только твои красивые глазки с губками, а остально уже и так очень мило\",\n                    replies: [\n                        { text: \"Ну спасибо да, хоть бери и снова показывай все)\", next: 'pokazat' },\n                        { text: \"Спасибо Димка, я ценю это\", next: 'tsenya' }\n                    ]\n                },\n                pokazat: {\n                    text: \"А ты покажи)\",\n                    replies: [\n                        { text: \"Подумаю..\", next: 'podumay' },\n                        { text: \"Ну Диииим...\", next: 'kapriz' }\n                    ]\n                },\n                pochemu: {\n                    text: \"Почему? ну потому что почемучка ты\",\n                    replies: [\n                        { text: \"Ну... ладно\", next: 'ladno' },\n                        { text: \"Ого... не знала..\", next: 'ne_znala' }\n                    ]\n                },\n                izvin: {\n                    text: \"Ты прям извиняшка очаровашка. Честно это мило когда ты частенько извиняешься по пустякам..\",\n                    replies: [\n                        { text: \"О как, я переживаю просто\", next: 'kak' },\n                        { text: \"Ну я просто переживаю что ты как то не так подумаешь или обидишься, поэтому извиняюсь\", next: 'kak' }\n                    ]\n                },\n                ne_mogu: {\n                    text: \"Не можешь... Вот и я не могу не расстроиться.\",\n                    replies: [\n                        { text: \"Почему?\", next: 'pochemu' },\n                        { text: \"Ты прав\", next: 'prav' }\n                    ]\n                },\n                ne_port: {\n                    text: \"Разработчик снова потерял тему за что болтали, за что такие боли....\",\n                    replies: [\n                        { text: \"Все норм, не преувеличивай!\", next: 'preuvel' },\n                        { text: \"Чмок короче Димка, люблю\", next: 'clarify' }\n                    ]\n                },\n                mysli: {\n                    text: \"обнимашки это приятно так то..\",\n                    replies: [\n                        { text: \"Ну вот и обними\", next: 'obimy' },\n                        { text: \"Ну ты как плюшевый мишка\", next: 'bear' }\n                    ]\n                },\n                obeshay: {\n                    text: \"*Тут я типо что то обещаю вроде или нет, но все равно меняем суть. хочу просто сказать что ты просто чудо, всего то.. но на самом деле это много что значит для меня*\",\n                    replies: [\n                        { text: \"Спасибо дим\", next: 'obeshanie' },\n                        { text: \"Ты тоже лучший дим\", next: 'obeshanie' }\n                    ]\n                },\n                horosho: {\n                    text: \"Хорошка ты\",\n                    replies: [\n                        { text: \"Ты тоже мили\", next: 'obeshanie' },\n                        { text: \"И ты\", next: 'obeshanie' }\n                    ]\n                },\n                podumay: {\n                    text: \"О чем мы там думаем?..\",\n                    replies: [\n                        { text: \"Ну ладно (не знаю)\", next: 'ladno' },\n                        { text: \"Ты прав (Другой ответ, но все равно ответ не знаю)\", next: 'prav' }\n                    ]\n                },\n                kapriz: {\n                    text: \"Капризности тебе не занимать кстати!\",\n                    replies: [\n                        { text: \"Нет, я мили!\", next: 'net' },\n                        { text: \"Ну капризная и че?\", next: 'da' }\n                    ]\n                },\n                ne_znala: {\n                    text: \"Ну теперь наверное знаешь, не знаю..\",\n                    replies: [\n                        { text: \"Ну да, ладно, когда диалог закончится?\", next: 'ladno' },\n                        { text: \"Порочный круг, ты прав..\", next: 'prav' }\n                    ]\n                },\n                kak: {\n                    text: \"Ты такая прям каак? честно я вообще уже потерял диалог, разраб устал :(\",\n                    replies: [\n                        { text: \"Ну.. что не остановился то?\", next: 'podumay' },\n                        { text: \"Это я капризни наверное\", next: 'kapriz' }\n                    ]\n                },\n                zato: {\n                    text: \"Зато... зато, зато.. Короче ты права, не знаю почему, просто тут снова пробел из-за того что димка и устал и не понимает что за вопрос был выше:( Тяжело так то\",\n                    replies: [\n                        { text: \"Почему?\", next: 'pochemu' },\n                        { text: \"Все хорошо, люблю просто\", next: 'love' }\n                    ]\n                },\n                ne_mogu2: {\n                    text: \"В общем можешь или не можешь или хочешь не хочешь ты все равно чудо. Милое обоятельное, просто прекрасное, люблю тебя\",\n                    replies: [\n                        { text: \"И я тебя люблю Димка\", next: 'love' },\n                        { text: \"Ты мили (ответ засчитает как я типо прав в чем то, что бы не делать тупик в диалоге)\", next: 'prav' }\n                    ]\n                },\n                obimy: {\n                    text: \"Обнимаю тебя в общем очень крепко сзади за животик и просто смотрю как ты сидишь как маленькая девочка в телефоне и залипаешь.\",\n                    replies: [\n                        { text: \"Милий ты мишка\", next: 'bear' },\n                        { text: \"Любимка ты мой\", next: 'clarify' }\n                    ]\n                },\n                obeshanie: {\n                    text: \"(Тут скорее всего тоже непонятно, просто выберем что то, а там будет видно?)\",\n                    replies: [\n                        { text: \"Почему?\", next: 'pochemu' },\n                        { text: \"Ты прав\", next: 'prav' }\n                    ]\n                },\n                net: {\n                    text: \"Самая милая, обоятельная, лучшая, красивая, интересная и блин, капризная)\",\n                    replies: [\n                        { text: \"Нет я сказала!\", next: 'net2' },\n                        { text: \"Ладно, есть немного (возможно тупик)\", next: 'prav' }\n                    ]\n                },\n                da: {\n                    text: \"Ну тебе везет что мы два сапожка пара\",\n                    replies: [\n                        { text: \"Агась\", next: 'prav' },\n                        { text: \"Пара так то\", next: 'clarify' }\n                    ]\n                },\n                net2: {\n                    text: \"Нет? да лизаветка\",\n                    replies: [\n                        { text: \"ну есть немного..\", next: 'prav' },\n                        { text: \"Ладно (все равно не будет выбора с *нет*)\", next: 'clarify' }\n                    ]\n                },\n                end: {\n                    text: \"Честно мне хочется сказать мне как я рад писать для тебя эти слова и просто рад тому что у меня начинает получаться писать этот сайт, делать какие-то пасхалки, где то тебе показывать где они и просто стараться сделать хоть и не все идеально, но красиво, мило и со вкусом. Мне нравиться вот так стараться что то делать для тебя на досуге. Это меня и успокоивает и я знаю что ты ждешь от меня этот проект где я со временем все стараюсь делать лучше и лучше. Я рад что и ты в меня веришь, я честно хотел это забросить и знаешь, мне нравиться что получается и я рад что это все ради тебя и делается по сути благодаря тебе. Я рад что такими стараниями я хоть порой не смогу удивлять прям, но улыбку как минимум сделаю. Честно мне изначально даже хотелось все это показать тебе вплоть до мелочей, но не было ведь бы той изюминки как сейчас, поэтому вот такая вот версия вышла. Еще раз спасибо за то что ты рядом, за то что переживаешь, ценишь, понимаешь. Да мы ссоримся, но я всегда хочу найти с тобой общий язык, стараюсь понять тебя, понять что для тебя важно, чем смогу помочь, просто отвлечь, все Лиз. Ты особенная девочка и ты мне нравишься такой и мне нравиться твой характер, твоя внешность и боже.. очень красивые глаза мне нравятся. Ты правда особенная, единственная такая и я думал вот чисто какой может быть для меня идеал, что бы и не было скучно и не было слишком тяжело эмоционально, в этом ты моя золотая серидина и в этом ты мой идеал, а дальше поживем увидем Лиз. Я просто хочу сказать что Люблю тебя и люблю то что ты делаешь. Чмок! ❤\",\n                    replies: null\n                }\n            };\n\n            // Индикатор набора живёт в конце ленты и всегда остаётся последним\n            var typingEl = document.createElement('div');\n            typingEl.className = 'tg-typing';\n            typingEl.setAttribute('aria-hidden', 'true');\n            for (var d = 0; d < 3; d++) typingEl.appendChild(document.createElement('span'));\n            messagesDiv.appendChild(typingEl);\n\n            function formatTime(date) {\n                return date.getHours().toString().padStart(2, '0') + ':' + date.getMinutes().toString().padStart(2, '0');\n            }\n\n            function scrollToBottom() {\n                messagesDiv.scrollTop = messagesDiv.scrollHeight;\n            }\n\n            // Оттенок фона зависит от текста сообщения\n            function moodHue(text) {\n                var h = 0;\n                for (var i = 0; i < text.length; i++) {\n                    h = (Math.imul(h, 31) + text.charCodeAt(i)) >>> 0;\n                }\n                return h % 360;\n            }\n\n            function applyMood(text) {\n                var hue = moodHue(text);\n                var style = document.body.style;\n                style.setProperty('--h1', String((hue + 12) % 360));\n                style.setProperty('--h2', String((hue + 160) % 360));\n            }\n\n            function addMessage(text, isBot) {\n                var now = new Date();\n\n                var row = document.createElement('div');\n                row.className = isBot ? 'message' : 'message message-new';\n\n                var avatarEl = document.createElement('figure');\n                avatarEl.className = 'avatar';\n                var imgEl = document.createElement('img');\n                imgEl.src = isBot ? BOT_AVATAR : USER_AVATAR;\n                imgEl.alt = '';\n                imgEl.loading = 'lazy';\n                avatarEl.appendChild(imgEl);\n\n                var textEl = document.createElement('div');\n                textEl.className = 'text';\n                textEl.textContent = text;\n\n                var timeEl = document.createElement('div');\n                timeEl.className = 'timestamp';\n                timeEl.textContent = formatTime(now);\n\n                row.appendChild(avatarEl);\n                row.appendChild(textEl);\n                row.appendChild(timeEl);\n\n                messagesDiv.insertBefore(row, typingEl);\n                scrollToBottom();\n            }\n\n            function setTyping(on) {\n                typingEl.classList.toggle('is-visible', on);\n                if (statusEl) {\n                    statusEl.textContent = on ? 'печатает…' : 'в сети';\n                    statusEl.classList.toggle('is-typing', on);\n                }\n                if (on) scrollToBottom();\n            }\n\n            function showReplies(replies) {\n                repliesContainer.innerHTML = '';\n                if (replies && replies.length > 0) {\n                    replies.forEach(function (reply) {\n                        var button = document.createElement('button');\n                        button.type = 'button';\n                        button.className = 'reply-btn';\n                        button.textContent = reply.text;\n                        button.disabled = waiting;\n                        button.addEventListener('click', function () {\n                            handleReply(reply.text, reply.next);\n                        });\n                        repliesContainer.appendChild(button);\n                    });\n                    repliesContainer.style.display = 'flex';\n                    scrollToBottom();\n                } else {\n                    repliesContainer.style.display = 'none';\n                }\n            }\n\n            function sendBotMessage(state) {\n                var response = botResponses[state];\n                if (response) {\n                    addMessage(response.text, true);\n                    applyMood(response.text);\n                    showReplies(response.replies);\n                } else {\n                    addMessage('Не понимать, я же заранее запрограмирован на ответы', true);\n                    showReplies(null);\n                }\n            }\n\n            function handleReply(text, nextState) {\n                if (waiting) return;\n                waiting = true;\n\n                addMessage(text, false);\n                repliesContainer.style.display = 'none';\n                repliesContainer.innerHTML = '';\n                setTyping(true);\n\n                var delay = 1500 + Math.random() * 1200;\n\n                setTimeout(function () {\n                    setTyping(false);\n                    var response = botResponses[nextState];\n\n                    if (response) {\n                        addMessage(response.text, true);\n                        applyMood(response.text);\n                    } else {\n                        addMessage('Интересно... 🤔 Расскажи подробнее.', true);\n                    }\n\n                    waiting = false;\n                    showReplies(response ? response.replies : null);\n                }, delay);\n            }\n\n            function startChat() {\n                if (started) return;\n                started = true;\n                setTyping(true);\n                setTimeout(function () {\n                    setTyping(false);\n                    sendBotMessage('start');\n                }, 900);\n            }\n\n            // --- Фото профиля ---\n            if (userAvatar) {\n                userAvatar.addEventListener('click', function () {\n                    modalImage.src = '../assets/images/secret/9.png';\n                    photoModal.classList.add('show');\n                });\n            }\n\n            closeModalBtn.addEventListener('click', function () {\n                photoModal.classList.remove('show');\n            });\n\n            photoModal.addEventListener('click', function (e) {\n                if (e.target === photoModal) {\n                    photoModal.classList.remove('show');\n                }\n            });\n\n            document.addEventListener('keydown', function (e) {\n                if (e.key === 'Escape') {\n                    photoModal.classList.remove('show');\n                }\n            });\n\n            setTimeout(startChat, 700);\n        });\n\n    </script>\n        <!-- Контейнер для снега -->\n    <div class=\"snowflakes-container\" id=\"snowContainer\"></div>\n    \r\n</body>\n</html>\n";